// Independently assembled modern ext4 fixtures, never generated by production codecs.
// Provenance: Linux ext4 superblock/GDT/inode/extent/directory/xattr format documentation.
// CRC32C uses the forward polynomial 0x1edc6f41 independently of the production loop.
fn w(b: &mut [u8], at: usize, value: u16) {
    b[at..at + 2].copy_from_slice(&value.to_le_bytes());
}
fn d(b: &mut [u8], at: usize, value: u32) {
    b[at..at + 4].copy_from_slice(&value.to_le_bytes());
}
fn forward(mut state: u32, bytes: &[u8]) -> u32 {
    state = state.reverse_bits();
    for &byte in bytes {
        state ^= u32::from(byte.reverse_bits()) << 24;
        for _ in 0..8 {
            let top = state & 0x80000000 != 0;
            state <<= 1;
            if top {
                state ^= 0x1edc6f41;
            }
        }
    }
    state.reverse_bits()
}
pub fn inode_checksum(image: &mut [u8], number: u32) {
    let at = 5 * 1024 + (number as usize - 1) * 256;
    w(image, at + 124, 0);
    w(image, at + 130, 0);
    let seed = forward(
        forward(0x12345678, &number.to_le_bytes()),
        &0u32.to_le_bytes(),
    );
    let checksum = forward(seed, &image[at..at + 256]);
    w(image, at + 124, checksum as u16);
    w(image, at + 130, (checksum >> 16) as u16);
}
pub fn xattr_checksum(image: &mut [u8]) {
    d(image, 12 * 1024 + 16, 0);
    let checksum = forward(
        forward(0x12345678, &12u64.to_le_bytes()),
        &image[12 * 1024..13 * 1024],
    );
    d(image, 12 * 1024 + 16, checksum);
}
// Entire accepted fixture assembled from format fields, never by a production codec.
pub fn fixture() -> (Vec<u8>, Vec<u8>) {
    let mut image = vec![0; 64 * 1024];
    let sb = &mut image[1024..2048];
    d(sb, 0, 16);
    d(sb, 4, 64);
    d(sb, 12, 51);
    d(sb, 16, 5);
    d(sb, 20, 1);
    d(sb, 32, 64);
    d(sb, 36, 64);
    d(sb, 40, 16);
    w(sb, 56, 0xef53);
    w(sb, 58, 1);
    d(sb, 76, 1);
    d(sb, 84, 11);
    w(sb, 88, 256);
    d(sb, 92, 8);
    d(sb, 96, 0x20c2);
    d(sb, 100, 0x443);
    w(sb, 254, 64);
    w(sb, 348, 32);
    w(sb, 350, 32);
    sb[373] = 1;
    d(sb, 624, 0x12345678);
    let checksum = forward(!0, &sb[..1020]);
    d(sb, 1020, checksum);
    for (number, mode, length, physical, count, sectors, links) in [
        (2, 0o40755, 1024, 9, 1, 4, 2),
        (12, 0o100644, 1700, 10, 2, 6, 1),
    ] {
        let at = 5 * 1024 + (number as usize - 1) * 256;
        let inode = &mut image[at..at + 256];
        w(inode, 0, mode);
        d(inode, 4, length);
        w(inode, 26, links);
        d(inode, 28, sectors);
        d(inode, 32, 0x80000);
        w(inode, 40, 0xf30a);
        w(inode, 42, 1);
        w(inode, 44, 4);
        w(inode, 56, count);
        d(inode, 60, physical);
        d(inode, 104, 12);
        w(inode, 128, 32);
        inode_checksum(&mut image, number);
    }
    let directory = &mut image[9 * 1024..10 * 1024];
    d(directory, 0, 2);
    w(directory, 4, 12);
    directory[6] = 1;
    directory[7] = 2;
    directory[8] = b'.';
    d(directory, 12, 2);
    w(directory, 16, 12);
    directory[18] = 2;
    directory[19] = 2;
    directory[20..22].copy_from_slice(b"..");
    d(directory, 24, 12);
    w(directory, 28, 988);
    directory[30] = 2;
    directory[31] = 1;
    directory[32..34].copy_from_slice(b"x\xff");
    w(directory, 1016, 12);
    directory[1019] = 0xde;
    let seed = forward(
        forward(0x12345678, &2u32.to_le_bytes()),
        &0u32.to_le_bytes(),
    );
    let checksum = forward(seed, &directory[..1012]);
    d(directory, 1020, checksum);
    let payload: Vec<u8> = (0..1700).map(|n| (n * 29 + n / 13) as u8).collect();
    image[10 * 1024..12 * 1024].fill(0xa5);
    image[10 * 1024..10 * 1024 + 1700].copy_from_slice(&payload);
    let ea = &mut image[12 * 1024..13 * 1024];
    d(ea, 0, 0xea020000);
    d(ea, 4, 2);
    d(ea, 8, 1);
    ea[32] = 1;
    ea[33] = 1;
    w(ea, 34, 1016);
    d(ea, 40, 8);
    ea[48] = b'x';
    ea[1016..1024].copy_from_slice(b"EA bytes");
    xattr_checksum(&mut image);
    image[3 * 1024..5 * 1024].fill(0xff);
    for bit in 12..63 {
        image[3 * 1024 + bit / 8] &= !(1 << (bit % 8));
    }
    image[4 * 1024] = 255;
    image[4 * 1024 + 1] = 0x0b;
    let bcrc = forward(0x12345678, &image[3 * 1024..3 * 1024 + 8]);
    let icrc = forward(0x12345678, &image[4 * 1024..4 * 1024 + 2]);
    let gd = &mut image[2048..2112];
    d(gd, 0, 3);
    d(gd, 4, 4);
    d(gd, 8, 5);
    w(gd, 12, 51);
    w(gd, 14, 5);
    w(gd, 16, 1);
    w(gd, 18, 4);
    w(gd, 24, bcrc as u16);
    w(gd, 56, (bcrc >> 16) as u16);
    w(gd, 26, icrc as u16);
    w(gd, 58, (icrc >> 16) as u16);
    let crc = forward(forward(0x12345678, &0u32.to_le_bytes()), gd);
    w(gd, 30, crc as u16);
    (image, payload)
}

pub fn without_extents() -> (Vec<u8>, Vec<u8>) {
    let (mut image, payload) = fixture();
    d(&mut image, 1024 + 96, 0x2082);
    let checksum = forward(!0, &image[1024..2044]);
    d(&mut image, 2044, checksum);
    for (number, pointers) in [(2, &[9u32][..]), (12, &[10u32, 11][..])] {
        let at = 5 * 1024 + (number as usize - 1) * 256;
        d(&mut image, at + 32, 0);
        image[at + 40..at + 100].fill(0);
        for (slot, block) in pointers.iter().enumerate() {
            d(&mut image, at + 40 + slot * 4, *block);
        }
        inode_checksum(&mut image, number);
    }
    (image, payload)
}
pub fn mutation_seeds() -> Vec<Vec<u8>> {
    (0..4)
        .map(|mutation| {
            let (mut image, _) = fixture();
            match mutation {
                0 => {
                    d(&mut image, 12 * 1024 + 4, 3);
                    xattr_checksum(&mut image);
                }
                1 => {
                    let at = 5 * 1024 + 11 * 256;
                    d(&mut image, at + 60, 12);
                    w(&mut image, at + 56, 1);
                    inode_checksum(&mut image, 12);
                }
                2 => image[5 * 1024 + 11 * 256 + 16] ^= 1,
                _ => {
                    d(&mut image, 2048 + 60, 1);
                    w(&mut image, 2048 + 30, 0);
                    let checksum =
                        forward(forward(0x12345678, &0u32.to_le_bytes()), &image[2048..2112]);
                    w(&mut image, 2048 + 30, checksum as u16);
                }
            }
            image
        })
        .collect()
}
